package com.rpis.backend.model;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.ArrayList;
import java.util.List;

/**
 * One subsection of a Terminal Report body section (e.g. {@code 4.1 Overall Production and
 * Market Change} in the official MSUN-Naawan terminal report format).
 *
 * <p>The subsection number is generated by the document renderer from the order of the
 * subsections, so the proponent only writes the heading and the text.</p>
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class TerminalReportSubsection {

    private String heading;
    private String text;

    /** True when the subsection carries text (a heading alone is not content). */
    public boolean hasText() {
        return text != null && !text.isBlank();
    }

    public static List<TerminalReportSubsection> emptyList() {
        return new ArrayList<>();
    }
}
